def main() -> None:
    names = set(E)
    for s, t, _, _ in R:
        assert s in names and t in names, (s, t)
    out = {"entities": [{"name": n, "type": t, "description": d} for n, (t, d) in E.items()],
           "relations": [{"source": s, "target": t, "description": d, "document": doc} for s, t, d, doc in R]}
    Path(__file__).with_name("curated_graph.json").write_text(json.dumps(out, indent=1))
    print(f"{len(E)} entities, {len(R)} relations")


if __name__ == "__main__":
    main()
